#include "web_server.h"

#include "esp_log.h"
#include "esp_mac.h"
#include "esp_wifi.h"
#include "esp_event.h"
#include "esp_netif.h"
#include "esp_system.h"
#include "nvs_flash.h"
#include "esp_http_server.h"
#include "soc/rtc_cntl_reg.h"
#include "input_state.h"
#include "usb_hid.h"
#include "display.h"

#include <string.h>

static const char *TAG = "web_server";

#define AP_SSID  "esp-remote"
#define AP_PASS  "esp32remote"

// Embedded web files (generated by EMBED_FILES in main/CMakeLists.txt)
extern const unsigned char index_html_start[] asm("_binary_index_html_start");
extern const unsigned char index_html_end[]   asm("_binary_index_html_end");
extern const unsigned char app_js_start[]     asm("_binary_app_js_start");
extern const unsigned char app_js_end[]       asm("_binary_app_js_end");

static httpd_handle_t s_server = NULL;
static int s_clients = 0;

// Protocol message types (must match web/app.js)
#define MSG_MOUSE     0x01   // [dx][dy][buttons][wheel]
#define MSG_KEYBOARD  0x02   // [mod][kc0..kc5]
#define MSG_CONSUMER  0x03   // [usage_lo][usage_hi]
#define MSG_PING      0x04
#define MSG_RELEASE   0x05

// ---------------------------------------------------------------------------
// WiFi SoftAP
// ---------------------------------------------------------------------------

static void wifi_event_handler(void *arg, esp_event_base_t base, int32_t id, void *data) {
    if (id == WIFI_EVENT_AP_STACONNECTED) {
        wifi_event_ap_staconnected_t *e = (wifi_event_ap_staconnected_t *)data;
        s_clients++;
        ESP_LOGI(TAG, "Client connected: " MACSTR " (now %d)", MAC2STR(e->mac), s_clients);
        display_status(6, "client joined");
    } else if (id == WIFI_EVENT_AP_STADISCONNECTED) {
        wifi_event_ap_stadisconnected_t *e = (wifi_event_ap_stadisconnected_t *)data;
        if (s_clients > 0) s_clients--;
        ESP_LOGI(TAG, "Client left: " MACSTR " (now %d)", MAC2STR(e->mac), s_clients);
        // Safety: never leave a key held after the controller vanishes.
        input_release_all();
        display_status(6, s_clients ? "client joined" : "no client");
    }
}

static esp_err_t wifi_init_softap(void) {
    ESP_ERROR_CHECK(esp_netif_init());
    ESP_ERROR_CHECK(esp_event_loop_create_default());
    esp_netif_create_default_wifi_ap();

    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
    ESP_ERROR_CHECK(esp_wifi_init(&cfg));

    ESP_ERROR_CHECK(esp_event_handler_instance_register(
        WIFI_EVENT, ESP_EVENT_ANY_ID, &wifi_event_handler, NULL, NULL));

    wifi_config_t wc = {
        .ap = {
            .ssid = AP_SSID,
            .ssid_len = strlen(AP_SSID),
            .channel = 1,
            .password = AP_PASS,
            .max_connection = 4,
            .authmode = WIFI_AUTH_WPA2_PSK,
        },
    };
    if (strlen(AP_PASS) == 0) wc.ap.authmode = WIFI_AUTH_OPEN;

    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_AP));
    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_AP, &wc));
    ESP_ERROR_CHECK(esp_wifi_start());
    // Modem sleep off: keeps HID latency low at the cost of power.
    ESP_ERROR_CHECK(esp_wifi_set_ps(WIFI_PS_NONE));

    ESP_LOGI(TAG, "SoftAP '%s' up, IP 192.168.4.1", AP_SSID);
    return ESP_OK;
}

// ---------------------------------------------------------------------------
// HTTP handlers
// ---------------------------------------------------------------------------

static esp_err_t index_handler(httpd_req_t *req) {
    httpd_resp_set_type(req, "text/html");
    return httpd_resp_send(req, (const char *)index_html_start,
                           index_html_end - index_html_start);
}

static esp_err_t appjs_handler(httpd_req_t *req) {
    httpd_resp_set_type(req, "application/javascript");
    return httpd_resp_send(req, (const char *)app_js_start,
                           app_js_end - app_js_start);
}

// Reboot straight into the ROM USB download mode, so the board can be
// reflashed over USB without touching the BOOT button.
//
// The flag lives in an RTC register, so it survives a soft reset but is
// cleared by a power cycle -- unplugging is always a safe way out.
// POST-only on purpose: a stray GET (or a link prefetch) must not trigger it.
static esp_err_t bootloader_handler(httpd_req_t *req) {
    if (req->method != HTTP_POST) {
        httpd_resp_send_err(req, HTTPD_405_METHOD_NOT_ALLOWED, "POST only");
        return ESP_FAIL;
    }

    ESP_LOGW(TAG, "Reboot to bootloader requested");
    input_release_all();

    httpd_resp_set_type(req, "text/plain");
    httpd_resp_send(req, "rebooting to download mode", HTTPD_RESP_USE_STRLEN);

    // Give the HTTP response time to actually leave the chip.
    vTaskDelay(pdMS_TO_TICKS(300));

    REG_WRITE(RTC_CNTL_OPTION1_REG, RTC_CNTL_FORCE_DOWNLOAD_BOOT);
    esp_restart();
    return ESP_OK;   // not reached
}

// ---------------------------------------------------------------------------
// WebSocket
// ---------------------------------------------------------------------------

// Static buffer: the protocol's largest message is 8 bytes. Avoiding malloc on
// every mouse move keeps the heap stable at 100+ messages/second.
static uint8_t s_ws_buf[64];

static void handle_message(const uint8_t *b, size_t len) {
    switch (b[0]) {
    case MSG_MOUSE:
        if (len >= 5) {
            input_mouse(b[3], (int8_t)b[1], (int8_t)b[2], (int8_t)b[4]);
        }
        break;
    case MSG_KEYBOARD:
        if (len >= 8) {
            uint8_t keys[6] = { b[2], b[3], b[4], b[5], b[6], b[7] };
            input_keyboard(b[1], keys);
        }
        break;
    case MSG_CONSUMER:
        if (len >= 3) {
            input_consumer((uint16_t)(b[1] | (b[2] << 8)));
        }
        break;
    case MSG_PING:
        input_heartbeat();
        break;
    case MSG_RELEASE:
        input_release_all();
        break;
    default:
        ESP_LOGW(TAG, "Unknown WS message 0x%02X", b[0]);
        break;
    }
}

static esp_err_t ws_handler(httpd_req_t *req) {
    if (req->method == HTTP_GET) {
        ESP_LOGI(TAG, "WebSocket handshake");
        return ESP_OK;
    }

    httpd_ws_frame_t pkt = { .type = HTTPD_WS_TYPE_BINARY };
    esp_err_t ret = httpd_ws_recv_frame(req, &pkt, 0);   // get length
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "ws_recv_frame(len) failed: %s", esp_err_to_name(ret));
        return ret;
    }
    if (pkt.len == 0) return ESP_OK;

    if (pkt.len > sizeof(s_ws_buf)) {
        ESP_LOGW(TAG, "Oversized WS frame (%u bytes), dropping session",
                 (unsigned)pkt.len);
        return ESP_FAIL;   // closes the session
    }

    pkt.payload = s_ws_buf;
    ret = httpd_ws_recv_frame(req, &pkt, pkt.len);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "ws_recv_frame(data) failed: %s", esp_err_to_name(ret));
        return ret;
    }

    handle_message(s_ws_buf, pkt.len);
    return ESP_OK;
}

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

esp_err_t web_server_start(void) {
    esp_err_t ret = nvs_flash_init();
    if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_ERROR_CHECK(nvs_flash_erase());
        ret = nvs_flash_init();
    }
    ESP_ERROR_CHECK(ret);

    ESP_ERROR_CHECK(wifi_init_softap());

    httpd_config_t cfg = HTTPD_DEFAULT_CONFIG();
    cfg.max_open_sockets = 7;
    cfg.lru_purge_enable = true;

    if (httpd_start(&s_server, &cfg) != ESP_OK) {
        ESP_LOGE(TAG, "httpd_start failed");
        return ESP_FAIL;
    }

    httpd_uri_t uris[] = {
        { .uri = "/",            .method = HTTP_GET,  .handler = index_handler },
        { .uri = "/app.js",      .method = HTTP_GET,  .handler = appjs_handler },
        { .uri = "/ws",          .method = HTTP_GET,  .handler = ws_handler, .is_websocket = true },
        { .uri = "/bootloader",  .method = HTTP_POST, .handler = bootloader_handler },
    };
    for (size_t i = 0; i < sizeof(uris) / sizeof(uris[0]); i++) {
        ESP_ERROR_CHECK(httpd_register_uri_handler(s_server, &uris[i]));
    }

    ESP_LOGI(TAG, "HTTP server started on port %d", cfg.server_port);
    return ESP_OK;
}

void web_server_stop(void) {
    if (s_server) {
        httpd_stop(s_server);
        s_server = NULL;
    }
}

int web_server_client_count(void) {
    return s_clients;
}
